BEGIN;
-- PostgreSQL 17 native UUID and SHA-256 functions avoid extension-schema assumptions.
DO $$ BEGIN
 IF to_regclass('public.office_workspaces') IS NULL OR to_regclass('public.office_memberships') IS NULL OR to_regclass('public.office_industry_spaces') IS NULL OR to_regprocedure('office_private.is_active_member(uuid)') IS NULL OR to_regprocedure('office_private.is_admin(uuid)') IS NULL THEN RAISE EXCEPTION 'Existing Office Team schemas are required'; END IF;
END $$;
CREATE SCHEMA IF NOT EXISTS office_private;
CREATE TABLE public.office_accounting_staff_roles(workspace_id uuid NOT NULL,user_id uuid NOT NULL,accounting_role text NOT NULL CHECK(accounting_role IN('engagement_manager','accountant','reviewer','client_coordinator','accounting_viewer')),active boolean NOT NULL DEFAULT true,assigned_by uuid REFERENCES auth.users(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(workspace_id,user_id),FOREIGN KEY(workspace_id,user_id) REFERENCES public.office_memberships(workspace_id,user_id) ON DELETE CASCADE);
CREATE TABLE public.office_accounting_settings(workspace_id uuid PRIMARY KEY REFERENCES public.office_workspaces(id) ON DELETE CASCADE,base_currency_code text NOT NULL DEFAULT 'TZS' CHECK(base_currency_code~'^[A-Z]{3}$'),fiscal_year_start_month smallint NOT NULL DEFAULT 1 CHECK(fiscal_year_start_month BETWEEN 1 AND 12),version bigint NOT NULL DEFAULT 1 CHECK(version>0),updated_by uuid REFERENCES auth.users(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.office_accounting_key_configs(workspace_id uuid PRIMARY KEY REFERENCES public.office_workspaces(id) ON DELETE CASCADE,salt bytea NOT NULL CHECK(octet_length(salt)=16),nonce bytea NOT NULL CHECK(octet_length(nonce)=12),ciphertext bytea NOT NULL CHECK(octet_length(ciphertext) BETWEEN 17 AND 32768),created_by uuid REFERENCES auth.users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.office_accounting_clients(client_id uuid PRIMARY KEY DEFAULT pg_catalog.gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES public.office_workspaces(id) ON DELETE CASCADE,client_code text NOT NULL,legal_name_public text NOT NULL,display_name text NOT NULL,status text NOT NULL CHECK(status IN('active','inactive')),country_code text NOT NULL,currency_code text NOT NULL CHECK(currency_code~'^[A-Z]{3}$'),public_reference text NOT NULL DEFAULT '',version bigint NOT NULL DEFAULT 1,created_by uuid REFERENCES auth.users(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(workspace_id,client_id),UNIQUE(workspace_id,client_code));
CREATE TABLE public.office_accounting_client_private(workspace_id uuid NOT NULL,client_id uuid NOT NULL,nonce bytea NOT NULL CHECK(octet_length(nonce)=12),ciphertext bytea NOT NULL CHECK(octet_length(ciphertext) BETWEEN 17 AND 32768),version bigint NOT NULL DEFAULT 1,updated_by uuid REFERENCES auth.users(id),updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(workspace_id,client_id),FOREIGN KEY(workspace_id,client_id) REFERENCES public.office_accounting_clients(workspace_id,client_id) ON DELETE RESTRICT);
CREATE TABLE public.office_accounting_staff_assignments(workspace_id uuid NOT NULL,client_id uuid NOT NULL,user_id uuid NOT NULL,active boolean NOT NULL DEFAULT true,assigned_by uuid REFERENCES auth.users(id),version bigint NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(workspace_id,client_id,user_id),FOREIGN KEY(workspace_id,client_id) REFERENCES public.office_accounting_clients(workspace_id,client_id) ON DELETE CASCADE,FOREIGN KEY(workspace_id,user_id) REFERENCES public.office_memberships(workspace_id,user_id) ON DELETE CASCADE);
CREATE TABLE public.office_accounting_engagements(engagement_id uuid PRIMARY KEY DEFAULT pg_catalog.gen_random_uuid(),workspace_id uuid NOT NULL,client_id uuid NOT NULL,engagement_code text NOT NULL,title text NOT NULL,engagement_type text NOT NULL CHECK(engagement_type IN('bookkeeping','review','audit_support','tax_compliance_tracking','other')),status text NOT NULL CHECK(status IN('planning','active','on_hold','closed')),period_start date,period_end date,lead_user_id uuid,description_public text NOT NULL DEFAULT '',version bigint NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(workspace_id,engagement_id),UNIQUE(workspace_id,client_id,engagement_code),FOREIGN KEY(workspace_id,client_id) REFERENCES public.office_accounting_clients(workspace_id,client_id) ON DELETE RESTRICT);
CREATE TABLE public.office_accounting_accounts(account_id uuid PRIMARY KEY DEFAULT pg_catalog.gen_random_uuid(),workspace_id uuid NOT NULL,client_id uuid NOT NULL,account_code text NOT NULL,account_name text NOT NULL,account_type text NOT NULL CHECK(account_type IN('asset','liability','equity','income','expense')),normal_balance text NOT NULL CHECK(normal_balance IN('debit','credit')),parent_account_id uuid,status text NOT NULL CHECK(status IN('active','archived')),version bigint NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),report_group text,UNIQUE(workspace_id,account_id),UNIQUE(workspace_id,client_id,account_code),FOREIGN KEY(workspace_id,client_id) REFERENCES public.office_accounting_clients(workspace_id,client_id),FOREIGN KEY(workspace_id,parent_account_id) REFERENCES public.office_accounting_accounts(workspace_id,account_id));
CREATE TABLE public.office_accounting_periods(period_id uuid PRIMARY KEY DEFAULT pg_catalog.gen_random_uuid(),workspace_id uuid NOT NULL,client_id uuid NOT NULL,period_label text NOT NULL,starts_on date NOT NULL,ends_on date NOT NULL,status text NOT NULL DEFAULT 'open' CHECK(status IN('open','closed')),closed_at timestamptz,closed_by uuid,reopen_count integer NOT NULL DEFAULT 0,version bigint NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(workspace_id,period_id),CHECK(ends_on>=starts_on),FOREIGN KEY(workspace_id,client_id) REFERENCES public.office_accounting_clients(workspace_id,client_id));
CREATE TABLE public.office_accounting_journals(journal_id uuid PRIMARY KEY DEFAULT pg_catalog.gen_random_uuid(),workspace_id uuid NOT NULL,client_id uuid NOT NULL,engagement_id uuid,period_id uuid NOT NULL,journal_number text NOT NULL,entry_date date NOT NULL,currency_code text NOT NULL CHECK(currency_code~'^[A-Z]{3}$'),description text NOT NULL,status text NOT NULL DEFAULT 'draft' CHECK(status IN('draft','submitted','returned','approved','posted','reversed')),prepared_by uuid NOT NULL,submitted_at timestamptz,reviewed_by uuid,reviewed_at timestamptz,posted_at timestamptz,posting_id uuid,total_debit numeric(18,2) NOT NULL DEFAULT 0,total_credit numeric(18,2) NOT NULL DEFAULT 0,version bigint NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(workspace_id,journal_id),UNIQUE(workspace_id,journal_number),FOREIGN KEY(workspace_id,client_id) REFERENCES public.office_accounting_clients(workspace_id,client_id),FOREIGN KEY(workspace_id,engagement_id) REFERENCES public.office_accounting_engagements(workspace_id,engagement_id),FOREIGN KEY(workspace_id,period_id) REFERENCES public.office_accounting_periods(workspace_id,period_id));
CREATE TABLE public.office_accounting_journal_lines(line_id uuid PRIMARY KEY DEFAULT pg_catalog.gen_random_uuid(),workspace_id uuid NOT NULL,journal_id uuid NOT NULL,line_no integer NOT NULL,account_id uuid NOT NULL,account_code_snapshot text NOT NULL,account_name_snapshot text NOT NULL,description text NOT NULL,debit numeric(18,2) NOT NULL DEFAULT 0,credit numeric(18,2) NOT NULL DEFAULT 0,source_reference text,version bigint NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(workspace_id,line_id),UNIQUE(workspace_id,journal_id,line_no),CHECK(debit>=0 AND credit>=0 AND ((debit>0 AND credit=0) OR (credit>0 AND debit=0))),FOREIGN KEY(workspace_id,journal_id) REFERENCES public.office_accounting_journals(workspace_id,journal_id),FOREIGN KEY(workspace_id,account_id) REFERENCES public.office_accounting_accounts(workspace_id,account_id));
CREATE TABLE public.office_accounting_postings(posting_id uuid PRIMARY KEY DEFAULT pg_catalog.gen_random_uuid(),workspace_id uuid NOT NULL,client_id uuid NOT NULL,journal_id uuid NOT NULL,posting_number text NOT NULL,posted_at timestamptz NOT NULL DEFAULT now(),posted_by uuid NOT NULL,currency_code text NOT NULL,total_debit numeric(18,2) NOT NULL,total_credit numeric(18,2) NOT NULL,immutable_receipt text NOT NULL,reversal_of_posting_id uuid,UNIQUE(workspace_id,posting_id),UNIQUE(workspace_id,journal_id),FOREIGN KEY(workspace_id,journal_id) REFERENCES public.office_accounting_journals(workspace_id,journal_id));
CREATE TABLE public.office_accounting_reversals(reversal_id uuid PRIMARY KEY DEFAULT pg_catalog.gen_random_uuid(),workspace_id uuid NOT NULL,client_id uuid NOT NULL,original_journal_id uuid NOT NULL,reversal_journal_id uuid NOT NULL,reason text NOT NULL,created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.office_accounting_bank_accounts(bank_account_id uuid PRIMARY KEY DEFAULT pg_catalog.gen_random_uuid(),workspace_id uuid NOT NULL,client_id uuid NOT NULL,account_id uuid NOT NULL,label text NOT NULL,currency_code text NOT NULL,status text NOT NULL DEFAULT 'active' CHECK(status IN('active','inactive')),last_statement_date date,version bigint NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(workspace_id,bank_account_id),FOREIGN KEY(workspace_id,client_id) REFERENCES public.office_accounting_clients(workspace_id,client_id),FOREIGN KEY(workspace_id,account_id) REFERENCES public.office_accounting_accounts(workspace_id,account_id));
CREATE TABLE public.office_accounting_statements(statement_id uuid PRIMARY KEY DEFAULT pg_catalog.gen_random_uuid(),workspace_id uuid NOT NULL,client_id uuid NOT NULL,bank_account_id uuid,statement_reference text NOT NULL,statement_date date NOT NULL,opening_balance numeric(18,2) NOT NULL,closing_balance numeric(18,2) NOT NULL,source text NOT NULL DEFAULT 'manual' CHECK(source IN('manual','imported')),import_fingerprint text,status text NOT NULL DEFAULT 'draft' CHECK(status IN('draft','reconciled','locked')),version bigint NOT NULL DEFAULT 1,created_by uuid,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(workspace_id,statement_id),FOREIGN KEY(workspace_id,client_id) REFERENCES public.office_accounting_clients(workspace_id,client_id),FOREIGN KEY(workspace_id,bank_account_id) REFERENCES public.office_accounting_bank_accounts(workspace_id,bank_account_id));
CREATE TABLE public.office_accounting_statement_lines(statement_line_id uuid PRIMARY KEY DEFAULT pg_catalog.gen_random_uuid(),workspace_id uuid NOT NULL,statement_id uuid NOT NULL,line_no integer NOT NULL,transaction_date date NOT NULL,description text NOT NULL,reference text,signed_amount numeric(18,2) NOT NULL,running_balance numeric(18,2),matched_journal_line_id uuid,matched_at timestamptz,matched_by uuid,exclusion_reason text,status text NOT NULL DEFAULT 'unmatched' CHECK(status IN('unmatched','matched','excluded')),version bigint NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(workspace_id,statement_line_id),UNIQUE(workspace_id,statement_id,line_no),FOREIGN KEY(workspace_id,statement_id) REFERENCES public.office_accounting_statements(workspace_id,statement_id),FOREIGN KEY(workspace_id,matched_journal_line_id) REFERENCES public.office_accounting_journal_lines(workspace_id,line_id));
CREATE TABLE public.office_accounting_evidence(evidence_id uuid PRIMARY KEY DEFAULT pg_catalog.gen_random_uuid(),workspace_id uuid NOT NULL,client_id uuid NOT NULL,engagement_id uuid NOT NULL,title text NOT NULL,evidence_type text NOT NULL,reference_url text,provider text NOT NULL CHECK(provider IN('Bunny','other','manual_reference')),external_object_key text,content_fingerprint text,confidentiality text NOT NULL CHECK(confidentiality IN('public','confidential','personal')),encrypted_memo bytea,status text NOT NULL DEFAULT 'active' CHECK(status IN('active','superseded')),version bigint NOT NULL DEFAULT 1,created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(workspace_id,client_id) REFERENCES public.office_accounting_clients(workspace_id,client_id),FOREIGN KEY(workspace_id,engagement_id) REFERENCES public.office_accounting_engagements(workspace_id,engagement_id));
CREATE TABLE public.office_accounting_findings(finding_id uuid PRIMARY KEY DEFAULT pg_catalog.gen_random_uuid(),workspace_id uuid NOT NULL,client_id uuid NOT NULL,engagement_id uuid NOT NULL,evidence_id uuid,finding_code text NOT NULL,title text NOT NULL,description_public text NOT NULL,severity text NOT NULL CHECK(severity IN('low','medium','high','critical')),status text NOT NULL DEFAULT 'open' CHECK(status IN('open','management_response','resolved','closed')),owner_user_id uuid,due_date date,resolution_public text,closed_by uuid,created_by uuid NOT NULL,version bigint NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(workspace_id,client_id) REFERENCES public.office_accounting_clients(workspace_id,client_id),FOREIGN KEY(workspace_id,engagement_id) REFERENCES public.office_accounting_engagements(workspace_id,engagement_id));
CREATE TABLE public.office_accounting_obligations(obligation_id uuid PRIMARY KEY DEFAULT pg_catalog.gen_random_uuid(),workspace_id uuid NOT NULL,client_id uuid NOT NULL,engagement_id uuid,obligation_type text NOT NULL,authority_label text NOT NULL,period_label text NOT NULL,due_date date NOT NULL,status text NOT NULL CHECK(status IN('planned','in_progress','ready','filed_reference_recorded','closed','overdue')),filing_reference text,filed_on date,official_link text,notes_public text NOT NULL DEFAULT '',version bigint NOT NULL DEFAULT 1,created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(workspace_id,client_id) REFERENCES public.office_accounting_clients(workspace_id,client_id),FOREIGN KEY(workspace_id,engagement_id) REFERENCES public.office_accounting_engagements(workspace_id,engagement_id));
CREATE TABLE public.office_accounting_requests(workspace_id uuid NOT NULL,idempotency_key uuid NOT NULL,actor_id uuid NOT NULL,action text NOT NULL,request_hash text NOT NULL,response jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(workspace_id,idempotency_key));
CREATE TABLE public.office_accounting_audit(audit_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,workspace_id uuid NOT NULL,client_id uuid,engagement_id uuid,actor_user_id uuid,action text NOT NULL,resource text NOT NULL,entity_id uuid,before_digest text,after_digest text,idempotency_key uuid,occurred_at timestamptz NOT NULL DEFAULT now());
CREATE OR REPLACE FUNCTION office_private.accounting_require(w uuid,roles text[] DEFAULT NULL,c uuid DEFAULT NULL) RETURNS text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$DECLARE r text;BEGIN IF auth.uid() IS NULL OR NOT office_private.is_active_member(w) OR NOT EXISTS(SELECT 1 FROM public.office_industry_spaces s WHERE s.workspace_id=w AND s.industry_id='accounting') THEN RAISE EXCEPTION 'Active Accounting Office Team membership required' USING ERRCODE='42501'; END IF;r:=CASE WHEN office_private.is_admin(w) THEN 'accounting_admin' ELSE coalesce((SELECT accounting_role FROM public.office_accounting_staff_roles WHERE workspace_id=w AND user_id=auth.uid() AND active),'unassigned') END;IF roles IS NOT NULL AND (r='unassigned' OR (r<>'accounting_admin' AND NOT(r=ANY(roles)))) THEN RAISE EXCEPTION 'Accounting role assignment required' USING ERRCODE='42501';END IF;IF c IS NOT NULL AND r<>'accounting_admin' AND NOT EXISTS(SELECT 1 FROM public.office_accounting_staff_assignments a WHERE a.workspace_id=w AND a.client_id=c AND a.user_id=auth.uid() AND a.active) THEN RAISE EXCEPTION 'Assigned client required' USING ERRCODE='42501';END IF;RETURN r;END$$;
CREATE OR REPLACE FUNCTION office_private.accounting_client_filter(w uuid) RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$SELECT CASE WHEN office_private.is_admin(w) THEN 'admin' WHEN EXISTS(SELECT 1 FROM public.office_accounting_staff_roles WHERE workspace_id=w AND user_id=auth.uid() AND active) THEN 'assigned' ELSE 'none' END$$;
CREATE OR REPLACE FUNCTION office_private.accounting_period_no_overlap() RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$BEGIN IF EXISTS(SELECT 1 FROM public.office_accounting_periods p WHERE p.workspace_id=NEW.workspace_id AND p.client_id=NEW.client_id AND p.period_id IS DISTINCT FROM NEW.period_id AND daterange(p.starts_on,p.ends_on,'[]')&&daterange(NEW.starts_on,NEW.ends_on,'[]')) THEN RAISE EXCEPTION 'Reporting periods cannot overlap' USING ERRCODE='23P01';END IF;RETURN NEW;END$$;
CREATE TRIGGER accounting_period_overlap BEFORE INSERT OR UPDATE ON public.office_accounting_periods FOR EACH ROW EXECUTE FUNCTION office_private.accounting_period_no_overlap();
CREATE OR REPLACE FUNCTION public.office_accounting_read(w uuid, resource text, f jsonb DEFAULT '{}'::jsonb, requested_limit integer DEFAULT 200, requested_offset integer DEFAULT 0) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE lim int:=least(greatest(coalesce(requested_limit,200),1),200); off int:=coalesce(requested_offset,0); c uuid; role text; n bigint; rows jsonb; asof date; ps date; pe date; ytd date; pid uuid; cur text;
BEGIN
 IF jsonb_typeof(coalesce(f,'{}'))<>'object' OR off<0 THEN RAISE EXCEPTION 'Invalid pagination or filter' USING ERRCODE='22023'; END IF;
 role:=office_private.accounting_require(w,NULL,NULL); c:=NULLIF(f->>'client_id','')::uuid; IF c IS NOT NULL THEN PERFORM office_private.accounting_require(w,NULL,c); END IF;
 IF resource='bootstrap' THEN IF role='unassigned' THEN RETURN jsonb_build_object('role',role,'capabilities','{}'::jsonb); END IF; RETURN jsonb_build_object('role',role,'capabilities',jsonb_build_object('reports',true),'settings',(SELECT to_jsonb(x) FROM public.office_accounting_settings x WHERE x.workspace_id=w)); END IF;
 IF resource='settings' THEN RETURN coalesce((SELECT to_jsonb(x) FROM public.office_accounting_settings x WHERE x.workspace_id=w),'{}'::jsonb); END IF;
 IF resource IN ('trial_balance','general_ledger','profit_and_loss','balance_sheet') THEN
  IF c IS NULL THEN RAISE EXCEPTION 'client_id required' USING ERRCODE='22023'; END IF;
  asof:=coalesce(NULLIF(f->>'as_of','')::date,current_date); cur:=(SELECT currency_code FROM public.office_accounting_clients WHERE workspace_id=w AND client_id=c);
  IF resource='general_ledger' THEN
   IF f ? 'period_id' THEN SELECT starts_on,ends_on INTO ps,pe FROM public.office_accounting_periods WHERE workspace_id=w AND period_id=(f->>'period_id')::uuid AND client_id=c; IF ps IS NULL THEN RAISE EXCEPTION 'Valid client reporting period required' USING ERRCODE='22023'; END IF; ELSE ps:=coalesce(NULLIF(f->>'starts_on','')::date,'0001-01-01'); pe:=coalesce(NULLIF(f->>'ends_on','')::date,asof); END IF;
   SELECT count(*) INTO n FROM public.office_accounting_journal_lines l JOIN public.office_accounting_journals j USING(workspace_id,journal_id) WHERE l.workspace_id=w AND j.client_id=c AND j.status='posted' AND j.entry_date BETWEEN ps AND pe;
   SELECT coalesce(jsonb_agg(jsonb_build_object('client_id',j.client_id,'journal_id',j.journal_id,'line_id',l.line_id,'entry_date',j.entry_date,'journal_number',j.journal_number,'account_id',l.account_id,'account_code',l.account_code_snapshot,'account_name',l.account_name_snapshot,'debit',l.debit,'credit',l.credit,'description',l.description,'currency_code',j.currency_code) ORDER BY j.entry_date,j.journal_number,l.line_no),'[]'::jsonb) INTO rows FROM (SELECT l.*,j.client_id,j.entry_date,j.journal_number,j.currency_code FROM public.office_accounting_journal_lines l JOIN public.office_accounting_journals j USING(workspace_id,journal_id) WHERE l.workspace_id=w AND j.client_id=c AND j.status='posted' AND j.entry_date BETWEEN ps AND pe ORDER BY j.entry_date,j.journal_number,l.line_no LIMIT lim OFFSET off) l JOIN public.office_accounting_journals j USING(workspace_id,journal_id);
  ELSE
   SELECT starts_on,ends_on,period_id INTO ps,pe,pid FROM public.office_accounting_periods WHERE workspace_id=w AND period_id=NULLIF(f->>'period_id','')::uuid AND client_id=c;
   IF f ? 'period_id' AND ps IS NULL THEN RAISE EXCEPTION 'Valid client reporting period required' USING ERRCODE='22023'; END IF;
   IF resource='profit_and_loss' THEN ps:=coalesce(ps,coalesce(NULLIF(f->>'starts_on','')::date,date_trunc('year',asof)::date)); pe:=coalesce(pe,asof); ELSE pe:=coalesce(pe,asof); END IF;
   SELECT count(*) INTO n FROM public.office_accounting_accounts a WHERE a.workspace_id=w AND a.client_id=c;
   SELECT coalesce(jsonb_agg(jsonb_build_object('client_id',a.client_id,'account_id',a.account_id,'account_code',a.account_code,'account_name',a.account_name,'account_type',a.account_type,'debit',x.debit,'credit',x.credit,'balance',CASE WHEN a.account_type IN('liability','equity','income') THEN x.credit-x.debit ELSE x.debit-x.credit END,'currency_code',cur) ORDER BY a.account_code),'[]'::jsonb) INTO rows FROM (SELECT a.*,coalesce((SELECT sum(l.debit) FROM public.office_accounting_journal_lines l JOIN public.office_accounting_journals j USING(workspace_id,journal_id) WHERE l.account_id=a.account_id AND j.client_id=c AND j.status='posted' AND j.entry_date<=pe AND (resource<>'profit_and_loss' OR j.entry_date>=ps)),0) debit,coalesce((SELECT sum(l.credit) FROM public.office_accounting_journal_lines l JOIN public.office_accounting_journals j USING(workspace_id,journal_id) WHERE l.account_id=a.account_id AND j.client_id=c AND j.status='posted' AND j.entry_date<=pe AND (resource<>'profit_and_loss' OR j.entry_date>=ps)),0) credit FROM public.office_accounting_accounts a WHERE a.workspace_id=w AND a.client_id=c AND (resource<>'profit_and_loss' OR a.account_type IN('income','expense')) ORDER BY a.account_code LIMIT lim OFFSET off) a JOIN LATERAL (SELECT a.debit,a.credit) x ON true;
  END IF;
  RETURN jsonb_build_object('report','internal_'||resource,'client_id',c,'rows',coalesce(rows,'[]'::jsonb),'total_count',n,'limit',lim,'offset',off,'has_more',off+jsonb_array_length(coalesce(rows,'[]'::jsonb))<n,'as_of',asof);
 END IF;
 IF resource='bank_statements' THEN
  IF c IS NULL THEN RAISE EXCEPTION 'client_id required' USING ERRCODE='22023'; END IF;
  n := (SELECT count(*) FROM public.office_accounting_statements WHERE workspace_id=w AND client_id=c);
  rows := (SELECT coalesce(jsonb_agg(to_jsonb(z) || jsonb_build_object('total_lines',(SELECT count(*) FROM public.office_accounting_statement_lines l WHERE l.workspace_id=w AND l.statement_id=z.statement_id),'matched_lines',(SELECT count(*) FROM public.office_accounting_statement_lines l WHERE l.workspace_id=w AND l.statement_id=z.statement_id AND l.status='matched'),'excluded_lines',(SELECT count(*) FROM public.office_accounting_statement_lines l WHERE l.workspace_id=w AND l.statement_id=z.statement_id AND l.status='excluded'),'unmatched_lines',(SELECT count(*) FROM public.office_accounting_statement_lines l WHERE l.workspace_id=w AND l.statement_id=z.statement_id AND l.status='unmatched'),'difference',z.opening_balance+coalesce((SELECT sum(l.signed_amount) FROM public.office_accounting_statement_lines l WHERE l.workspace_id=w AND l.statement_id=z.statement_id),0)-z.closing_balance,'is_balanced',(z.opening_balance+coalesce((SELECT sum(l.signed_amount) FROM public.office_accounting_statement_lines l WHERE l.workspace_id=w AND l.statement_id=z.statement_id),0)=z.closing_balance AND (SELECT count(*) FROM public.office_accounting_statement_lines l WHERE l.workspace_id=w AND l.statement_id=z.statement_id AND l.status='unmatched')=0 AND (SELECT count(*) FROM public.office_accounting_statement_lines l WHERE l.workspace_id=w AND l.statement_id=z.statement_id)>0))),'[]'::jsonb) FROM (SELECT s.* FROM public.office_accounting_statements s WHERE s.workspace_id=w AND s.client_id=c ORDER BY s.statement_date DESC,s.statement_reference LIMIT lim OFFSET off) z);
  RETURN jsonb_build_object('rows',coalesce(rows,'[]'::jsonb),'total_count',n,'limit',lim,'offset',off,'has_more',off+jsonb_array_length(coalesce(rows,'[]'::jsonb))<n,'client_id',c);
 END IF;
 IF resource='client_private' THEN IF c IS NULL THEN RAISE EXCEPTION 'client_id required' USING ERRCODE='22023'; END IF; RETURN coalesce((SELECT jsonb_build_object('workspace_id',workspace_id,'client_id',client_id,'nonce',encode(nonce,'base64'),'ciphertext',encode(ciphertext,'base64'),'version',version) FROM public.office_accounting_client_private WHERE workspace_id=w AND client_id=c),'{}'::jsonb); END IF;
 IF resource='chart_accounts' THEN SELECT count(*) INTO n FROM public.office_accounting_accounts a WHERE a.workspace_id=w AND (c IS NULL OR a.client_id=c); SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY x.account_code),'[]'::jsonb) INTO rows FROM (SELECT a.* FROM public.office_accounting_accounts a WHERE a.workspace_id=w AND (c IS NULL OR a.client_id=c) ORDER BY a.account_code LIMIT lim OFFSET off) x;
 ELSIF resource='clients' THEN SELECT count(*) INTO n FROM public.office_accounting_clients x WHERE x.workspace_id=w AND (role='accounting_admin' OR EXISTS(SELECT 1 FROM public.office_accounting_staff_assignments z WHERE z.workspace_id=w AND z.client_id=x.client_id AND z.user_id=auth.uid() AND z.active)); SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY x.created_at DESC),'[]'::jsonb) INTO rows FROM (SELECT x.* FROM public.office_accounting_clients x WHERE x.workspace_id=w AND (role='accounting_admin' OR EXISTS(SELECT 1 FROM public.office_accounting_staff_assignments z WHERE z.workspace_id=w AND z.client_id=x.client_id AND z.user_id=auth.uid() AND z.active)) ORDER BY x.created_at DESC LIMIT lim OFFSET off) x;
 ELSE RAISE EXCEPTION 'Unknown Accounting resource' USING ERRCODE='22023'; END IF;
 RETURN jsonb_build_object('rows',coalesce(rows,'[]'::jsonb),'total_count',coalesce(n,0),'limit',lim,'offset',off,'has_more',off+jsonb_array_length(coalesce(rows,'[]'::jsonb))<coalesce(n,0));
END$$;
CREATE OR REPLACE FUNCTION public.office_accounting_command(p_workspace_id uuid,p_action text,p_payload jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE role text;idem uuid;edate date;old text;result jsonb;h text;cid uuid;jid uuid;lid uuid;aid uuid;pid uuid;eid uuid;sid uuid;stid uuid;src uuid;target uuid;url text;d numeric;cr numeric;cnt int;v bigint;BEGIN IF p_payload IS NULL OR jsonb_typeof(p_payload)<>'object' THEN RAISE EXCEPTION 'Object payload required' USING ERRCODE='22023';END IF;idem:=NULLIF(p_payload->>'idempotency_key','')::uuid;IF idem IS NULL THEN RAISE EXCEPTION 'idempotency_key required' USING ERRCODE='22023';END IF;role:=office_private.accounting_require(p_workspace_id,NULL,NULL);h:=encode(pg_catalog.sha256(pg_catalog.convert_to(p_action||':'||p_payload::text,'UTF8')),'hex');SELECT response,request_hash INTO result,old FROM public.office_accounting_requests WHERE workspace_id=p_workspace_id AND idempotency_key=idem FOR UPDATE;IF FOUND THEN IF old<>h THEN RAISE EXCEPTION 'Idempotency key payload conflict' USING ERRCODE='23505';END IF;RETURN result;END IF;cid:=NULLIF(p_payload->>'client_id','')::uuid;IF cid IS NOT NULL THEN PERFORM office_private.accounting_require(p_workspace_id,NULL,cid);END IF;
IF p_action='save_accounting_settings' THEN PERFORM office_private.accounting_require(p_workspace_id,ARRAY['accounting_admin']);INSERT INTO public.office_accounting_settings(workspace_id,base_currency_code,fiscal_year_start_month,updated_by) VALUES(p_workspace_id,p_payload->>'base_currency_code',coalesce((p_payload->>'fiscal_year_start_month')::int,1),auth.uid()) ON CONFLICT(workspace_id) DO UPDATE SET base_currency_code=excluded.base_currency_code,fiscal_year_start_month=excluded.fiscal_year_start_month,version=office_accounting_settings.version+1,updated_by=auth.uid(),updated_at=now() RETURNING to_jsonb(office_accounting_settings.*) INTO result;
ELSIF p_action='save_client' THEN PERFORM office_private.accounting_require(p_workspace_id,ARRAY['accounting_admin','engagement_manager']);cid:=coalesce(cid,pg_catalog.gen_random_uuid());IF p_payload ? 'client_id' THEN IF NOT (p_payload ? 'expected_version') THEN RAISE EXCEPTION 'expected_version required' USING ERRCODE='40001'; END IF; UPDATE public.office_accounting_clients SET legal_name_public=coalesce(p_payload->>'legal_name_public',legal_name_public),display_name=coalesce(p_payload->>'display_name',display_name),status=coalesce(p_payload->>'status',status),country_code=coalesce(p_payload->>'country_code',country_code),currency_code=coalesce(p_payload->>'currency_code',currency_code),public_reference=coalesce(p_payload->>'public_reference',public_reference),version=version+1,updated_at=now() WHERE workspace_id=p_workspace_id AND client_id=cid AND version=(p_payload->>'expected_version')::bigint RETURNING to_jsonb(office_accounting_clients.*) INTO result;IF result IS NULL THEN RAISE EXCEPTION 'Client version conflict' USING ERRCODE='40001';END IF;ELSE INSERT INTO public.office_accounting_clients(client_id,workspace_id,client_code,legal_name_public,display_name,status,country_code,currency_code,public_reference,created_by) VALUES(cid,p_workspace_id,p_payload->>'client_code',p_payload->>'legal_name_public',p_payload->>'display_name',coalesce(p_payload->>'status','active'),p_payload->>'country_code',p_payload->>'currency_code',coalesce(p_payload->>'public_reference',''),auth.uid()) RETURNING to_jsonb(office_accounting_clients.*) INTO result;END IF;
ELSIF p_action='save_client_private' THEN PERFORM office_private.accounting_require(p_workspace_id,ARRAY['accounting_admin','engagement_manager','accountant'],cid);INSERT INTO public.office_accounting_client_private(workspace_id,client_id,nonce,ciphertext,updated_by) VALUES(p_workspace_id,cid,decode(p_payload->>'nonce','base64'),decode(p_payload->>'ciphertext','base64'),auth.uid()) ON CONFLICT(workspace_id,client_id) DO UPDATE SET nonce=excluded.nonce,ciphertext=excluded.ciphertext,version=office_accounting_client_private.version+1,updated_by=auth.uid(),updated_at=now() RETURNING jsonb_build_object('workspace_id',workspace_id,'client_id',client_id,'nonce',encode(nonce,'base64'),'ciphertext',encode(ciphertext,'base64'),'version',version,'updated_at',updated_at) INTO result;
ELSIF p_action='configure_private_key' THEN PERFORM office_private.accounting_require(p_workspace_id,ARRAY['accounting_admin']);INSERT INTO public.office_accounting_key_configs(workspace_id,salt,nonce,ciphertext,created_by) VALUES(p_workspace_id,decode(p_payload->>'salt','base64'),decode(p_payload->>'nonce','base64'),decode(p_payload->>'ciphertext','base64'),auth.uid()) ON CONFLICT(workspace_id) DO UPDATE SET salt=excluded.salt,nonce=excluded.nonce,ciphertext=excluded.ciphertext RETURNING jsonb_build_object('workspace_id',workspace_id,'created_at',created_at) INTO result;
ELSIF p_action='assign_client_staff' THEN PERFORM office_private.accounting_require(p_workspace_id,ARRAY['accounting_admin']);INSERT INTO public.office_accounting_staff_assignments(workspace_id,client_id,user_id,active,assigned_by) VALUES(p_workspace_id,cid,(p_payload->>'user_id')::uuid,coalesce((p_payload->>'active')::boolean,true),auth.uid()) ON CONFLICT(workspace_id,client_id,user_id) DO UPDATE SET active=excluded.active,version=office_accounting_staff_assignments.version+1,updated_at=now() RETURNING to_jsonb(office_accounting_staff_assignments.*) INTO result;
ELSIF p_action='save_engagement' THEN PERFORM office_private.accounting_require(p_workspace_id,ARRAY['accounting_admin','engagement_manager','accountant','client_coordinator'],cid);eid:=coalesce(NULLIF(p_payload->>'engagement_id','')::uuid,pg_catalog.gen_random_uuid());IF p_payload ? 'engagement_id' THEN IF NOT (p_payload ? 'expected_version') THEN RAISE EXCEPTION 'expected_version required' USING ERRCODE='40001'; END IF; UPDATE public.office_accounting_engagements SET title=coalesce(p_payload->>'title',title),status=coalesce(p_payload->>'status',status),description_public=coalesce(p_payload->>'description_public',description_public),version=version+1,updated_at=now() WHERE workspace_id=p_workspace_id AND engagement_id=eid AND version=(p_payload->>'expected_version')::bigint RETURNING to_jsonb(office_accounting_engagements.*) INTO result;ELSE INSERT INTO public.office_accounting_engagements(engagement_id,workspace_id,client_id,engagement_code,title,engagement_type,status,period_start,period_end,lead_user_id,description_public) VALUES(eid,p_workspace_id,cid,p_payload->>'engagement_code',p_payload->>'title',p_payload->>'engagement_type',coalesce(p_payload->>'status','planning'),(p_payload->>'period_start')::date,(p_payload->>'period_end')::date,(p_payload->>'lead_user_id')::uuid,coalesce(p_payload->>'description_public','')) RETURNING to_jsonb(office_accounting_engagements.*) INTO result;END IF;
ELSIF p_action='transition_engagement' THEN IF NOT (p_payload ? 'expected_version') THEN RAISE EXCEPTION 'expected_version required' USING ERRCODE='40001'; END IF; eid:=(p_payload->>'engagement_id')::uuid;SELECT client_id INTO cid FROM public.office_accounting_engagements WHERE workspace_id=p_workspace_id AND engagement_id=eid;PERFORM office_private.accounting_require(p_workspace_id,ARRAY['accounting_admin','engagement_manager'],cid);UPDATE public.office_accounting_engagements SET status=p_payload->>'status',version=version+1,updated_at=now() WHERE workspace_id=p_workspace_id AND engagement_id=eid AND version=(p_payload->>'expected_version')::bigint RETURNING to_jsonb(office_accounting_engagements.*) INTO result;
ELSIF p_action IN('save_chart_account','archive_chart_account') THEN PERFORM office_private.accounting_require(p_workspace_id,ARRAY['accounting_admin','engagement_manager','accountant'],cid);aid:=NULLIF(p_payload->>'account_id','')::uuid;IF p_action='archive_chart_account' THEN IF NOT (p_payload ? 'expected_version') THEN RAISE EXCEPTION 'expected_version required' USING ERRCODE='40001'; END IF; IF EXISTS(SELECT 1 FROM public.office_accounting_journal_lines l JOIN public.office_accounting_journals j USING(workspace_id,journal_id) WHERE l.workspace_id=p_workspace_id AND l.account_id=aid AND j.client_id=cid AND j.status='posted') THEN RAISE EXCEPTION 'Posted journal account is immutable' USING ERRCODE='55000'; END IF; UPDATE public.office_accounting_accounts SET status='archived',version=version+1,updated_at=now() WHERE workspace_id=p_workspace_id AND client_id=cid AND account_id=aid AND version=(p_payload->>'expected_version')::bigint RETURNING to_jsonb(office_accounting_accounts.*) INTO result;ELSE aid:=coalesce(aid,pg_catalog.gen_random_uuid());IF p_payload ? 'account_id' THEN IF NOT (p_payload ? 'expected_version') THEN RAISE EXCEPTION 'expected_version required' USING ERRCODE='40001'; END IF; IF EXISTS(SELECT 1 FROM public.office_accounting_journal_lines l JOIN public.office_accounting_journals j USING(workspace_id,journal_id) WHERE l.workspace_id=p_workspace_id AND l.account_id=aid AND j.client_id=cid AND j.status='posted') THEN RAISE EXCEPTION 'Posted journal account is immutable' USING ERRCODE='55000'; END IF; UPDATE public.office_accounting_accounts SET account_name=coalesce(p_payload->>'account_name',account_name),status=coalesce(p_payload->>'status',status),account_type=coalesce(p_payload->>'account_type',account_type),normal_balance=coalesce(p_payload->>'normal_balance',normal_balance),parent_account_id=coalesce((p_payload->>'parent_account_id')::uuid,parent_account_id),report_group=coalesce(p_payload->>'report_group',report_group),version=version+1,updated_at=now() WHERE workspace_id=p_workspace_id AND client_id=cid AND account_id=aid AND version=(p_payload->>'expected_version')::bigint RETURNING to_jsonb(office_accounting_accounts.*) INTO result; ELSE INSERT INTO public.office_accounting_accounts(account_id,workspace_id,client_id,account_code,account_name,account_type,normal_balance,parent_account_id,status,report_group) VALUES(aid,p_workspace_id,cid,p_payload->>'account_code',p_payload->>'account_name',p_payload->>'account_type',p_payload->>'normal_balance',(p_payload->>'parent_account_id')::uuid,coalesce(p_payload->>'status','active'),p_payload->>'report_group') RETURNING to_jsonb(office_accounting_accounts.*) INTO result; END IF;END IF;IF result IS NULL THEN RAISE EXCEPTION 'Chart account version or scope conflict' USING ERRCODE='40001';END IF;
ELSIF p_action='save_reporting_period' THEN PERFORM office_private.accounting_require(p_workspace_id,ARRAY['accounting_admin','engagement_manager','accountant'],cid);IF p_payload ? 'period_id' THEN pid:=(p_payload->>'period_id')::uuid;IF NOT (p_payload ? 'expected_version') THEN RAISE EXCEPTION 'expected_version required' USING ERRCODE='40001'; END IF; UPDATE public.office_accounting_periods SET period_label=p_payload->>'period_label',starts_on=(p_payload->>'starts_on')::date,ends_on=(p_payload->>'ends_on')::date,version=version+1,updated_at=now() WHERE workspace_id=p_workspace_id AND period_id=pid AND client_id=cid AND version=(p_payload->>'expected_version')::bigint RETURNING to_jsonb(office_accounting_periods.*) INTO result;ELSE pid:=pg_catalog.gen_random_uuid();INSERT INTO public.office_accounting_periods(period_id,workspace_id,client_id,period_label,starts_on,ends_on,status) VALUES(pid,p_workspace_id,cid,p_payload->>'period_label',(p_payload->>'starts_on')::date,(p_payload->>'ends_on')::date,coalesce(p_payload->>'status','open')) RETURNING to_jsonb(office_accounting_periods.*) INTO result;END IF;
ELSIF p_action IN('close_reporting_period','reopen_reporting_period') THEN IF length(trim(coalesce(p_payload->>'reason','')))<1 OR NOT (p_payload ? 'expected_version') THEN RAISE EXCEPTION 'Reason and expected_version required' USING ERRCODE='22023'; END IF; PERFORM office_private.accounting_require(p_workspace_id,CASE WHEN p_action='reopen_reporting_period' THEN ARRAY['accounting_admin','engagement_manager'] ELSE ARRAY['accounting_admin','engagement_manager','accountant'] END,cid); pid:=(p_payload->>'period_id')::uuid; IF p_action='close_reporting_period' AND (EXISTS(SELECT 1 FROM public.office_accounting_journals WHERE workspace_id=p_workspace_id AND period_id=pid AND status NOT IN('posted','reversed')) OR EXISTS(SELECT 1 FROM public.office_accounting_statements WHERE workspace_id=p_workspace_id AND client_id=cid AND status<>'locked' AND statement_date BETWEEN (SELECT starts_on FROM public.office_accounting_periods WHERE workspace_id=p_workspace_id AND period_id=pid) AND (SELECT ends_on FROM public.office_accounting_periods WHERE workspace_id=p_workspace_id AND period_id=pid))) THEN RAISE EXCEPTION 'Non-terminal journals or unlocked statements prevent close' USING ERRCODE='55000'; END IF; UPDATE public.office_accounting_periods SET status=CASE WHEN p_action='close_reporting_period' THEN 'closed' ELSE 'open' END,closed_at=CASE WHEN p_action='close_reporting_period' THEN now() ELSE NULL END,closed_by=CASE WHEN p_action='close_reporting_period' THEN auth.uid() ELSE NULL END,reopen_count=reopen_count+CASE WHEN p_action='reopen_reporting_period' THEN 1 ELSE 0 END,version=version+1,updated_at=now() WHERE workspace_id=p_workspace_id AND period_id=pid AND client_id=cid AND version=(p_payload->>'expected_version')::bigint RETURNING to_jsonb(office_accounting_periods.*) INTO result;IF result IS NULL THEN RAISE EXCEPTION 'Reporting period version or scope conflict' USING ERRCODE='40001';END IF;
ELSIF p_action='save_journal' THEN PERFORM office_private.accounting_require(p_workspace_id,ARRAY['accounting_admin','engagement_manager','accountant'],cid);jid:=coalesce(NULLIF(p_payload->>'journal_id','')::uuid,pg_catalog.gen_random_uuid());IF p_payload ? 'journal_id' THEN UPDATE public.office_accounting_journals SET description=coalesce(p_payload->>'description',description),entry_date=coalesce((p_payload->>'entry_date')::date,entry_date),version=version+1,updated_at=now() WHERE workspace_id=p_workspace_id AND journal_id=jid AND client_id=cid AND status IN('draft','returned') AND version=(p_payload->>'expected_version')::bigint RETURNING to_jsonb(office_accounting_journals.*) INTO result;ELSE INSERT INTO public.office_accounting_journals(journal_id,workspace_id,client_id,engagement_id,period_id,journal_number,entry_date,currency_code,description,prepared_by) VALUES(jid,p_workspace_id,cid,(p_payload->>'engagement_id')::uuid,(p_payload->>'period_id')::uuid,coalesce(p_payload->>'journal_number','J-'||substr(jid::text,1,8)),(p_payload->>'entry_date')::date,p_payload->>'currency_code',p_payload->>'description',auth.uid()) RETURNING to_jsonb(office_accounting_journals.*) INTO result;END IF;
ELSIF p_action='save_journal_line' THEN jid:=(p_payload->>'journal_id')::uuid;IF NOT (p_payload ? 'expected_parent_version') THEN RAISE EXCEPTION 'expected_parent_version required' USING ERRCODE='40001'; END IF;SELECT j.client_id,j.version INTO cid,v FROM public.office_accounting_journals j WHERE j.workspace_id=p_workspace_id AND j.journal_id=jid AND j.status IN('draft','returned') FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'Editable journal required' USING ERRCODE='55000'; END IF;PERFORM office_private.accounting_require(p_workspace_id,ARRAY['accounting_admin','engagement_manager','accountant'],cid);IF v<>(p_payload->>'expected_parent_version')::bigint THEN RAISE EXCEPTION 'Parent version conflict' USING ERRCODE='40001'; END IF;aid:=(p_payload->>'account_id')::uuid;IF p_payload ? 'line_id' THEN IF NOT (p_payload ? 'expected_version') THEN RAISE EXCEPTION 'expected_version required' USING ERRCODE='40001'; END IF;lid:=(p_payload->>'line_id')::uuid;UPDATE public.office_accounting_journal_lines SET account_id=aid,account_code_snapshot=(SELECT account_code FROM public.office_accounting_accounts WHERE workspace_id=p_workspace_id AND account_id=aid AND client_id=cid AND status='active'),account_name_snapshot=(SELECT account_name FROM public.office_accounting_accounts WHERE workspace_id=p_workspace_id AND account_id=aid AND client_id=cid AND status='active'),description=p_payload->>'description',debit=(p_payload->>'debit')::numeric,credit=(p_payload->>'credit')::numeric,version=version+1,updated_at=now() WHERE workspace_id=p_workspace_id AND journal_id=jid AND line_id=lid AND version=(p_payload->>'expected_version')::bigint RETURNING to_jsonb(office_accounting_journal_lines.*) INTO result;ELSE INSERT INTO public.office_accounting_journal_lines(workspace_id,journal_id,line_no,account_id,account_code_snapshot,account_name_snapshot,description,debit,credit,source_reference) SELECT p_workspace_id,jid,(p_payload->>'line_no')::int,a.account_id,a.account_code,a.account_name,p_payload->>'description',(p_payload->>'debit')::numeric,(p_payload->>'credit')::numeric,p_payload->>'source_reference' FROM public.office_accounting_accounts a WHERE a.workspace_id=p_workspace_id AND a.account_id=aid AND a.client_id=cid AND a.status='active' RETURNING to_jsonb(office_accounting_journal_lines.*) INTO result;END IF;IF result IS NULL THEN RAISE EXCEPTION 'Journal line version or account conflict' USING ERRCODE='40001';END IF;UPDATE public.office_accounting_journals SET version=version+1,total_debit=(SELECT coalesce(sum(l.debit),0) FROM public.office_accounting_journal_lines l WHERE l.workspace_id=p_workspace_id AND l.journal_id=jid),total_credit=(SELECT coalesce(sum(l.credit),0) FROM public.office_accounting_journal_lines l WHERE l.workspace_id=p_workspace_id AND l.journal_id=jid),updated_at=now() WHERE workspace_id=p_workspace_id AND journal_id=jid AND version=v RETURNING version INTO v;IF NOT FOUND THEN RAISE EXCEPTION 'Parent version conflict' USING ERRCODE='40001';END IF;result:=result||jsonb_build_object('parent_version',v);
ELSIF p_action='delete_journal_line' THEN jid:=(p_payload->>'journal_id')::uuid;IF NOT (p_payload ? 'expected_parent_version') OR NOT (p_payload ? 'expected_version') THEN RAISE EXCEPTION 'expected_parent_version and expected_version required' USING ERRCODE='40001'; END IF;SELECT client_id,version INTO cid,v FROM public.office_accounting_journals WHERE workspace_id=p_workspace_id AND journal_id=jid AND status IN('draft','returned') FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'Editable journal required' USING ERRCODE='55000'; END IF;PERFORM office_private.accounting_require(p_workspace_id,ARRAY['accounting_admin','engagement_manager','accountant'],cid);IF v<>(p_payload->>'expected_parent_version')::bigint THEN RAISE EXCEPTION 'Parent version conflict' USING ERRCODE='40001';END IF;DELETE FROM public.office_accounting_journal_lines WHERE workspace_id=p_workspace_id AND journal_id=jid AND line_id=(p_payload->>'line_id')::uuid AND version=(p_payload->>'expected_version')::bigint RETURNING jsonb_build_object('deleted',true,'line_id',line_id) INTO result;IF result IS NULL THEN RAISE EXCEPTION 'Journal line version conflict' USING ERRCODE='40001';END IF;UPDATE public.office_accounting_journals SET version=version+1,total_debit=(SELECT coalesce(sum(l.debit),0) FROM public.office_accounting_journal_lines l WHERE l.workspace_id=p_workspace_id AND l.journal_id=jid),total_credit=(SELECT coalesce(sum(l.credit),0) FROM public.office_accounting_journal_lines l WHERE l.workspace_id=p_workspace_id AND l.journal_id=jid),updated_at=now() WHERE workspace_id=p_workspace_id AND journal_id=jid AND version=v RETURNING version INTO v;IF NOT FOUND THEN RAISE EXCEPTION 'Parent version conflict' USING ERRCODE='40001';END IF;result:=result||jsonb_build_object('parent_version',v);
ELSIF p_action='submit_journal' THEN jid:=(p_payload->>'journal_id')::uuid;IF NOT (p_payload ? 'expected_version') THEN RAISE EXCEPTION 'expected_version required' USING ERRCODE='40001'; END IF;SELECT client_id,period_id,entry_date,version INTO cid,pid,edate,v FROM public.office_accounting_journals WHERE workspace_id=p_workspace_id AND journal_id=jid AND status IN('draft','returned') FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'Editable journal required' USING ERRCODE='55000'; END IF;PERFORM office_private.accounting_require(p_workspace_id,ARRAY['accounting_admin','engagement_manager','accountant'],cid);IF v<>(p_payload->>'expected_version')::bigint THEN RAISE EXCEPTION 'Journal version conflict' USING ERRCODE='40001';END IF;IF NOT EXISTS(SELECT 1 FROM public.office_accounting_periods WHERE workspace_id=p_workspace_id AND period_id=pid AND client_id=cid AND status='open' AND edate BETWEEN starts_on AND ends_on) THEN RAISE EXCEPTION 'Open period required' USING ERRCODE='55000';END IF;PERFORM 1 FROM public.office_accounting_journal_lines WHERE workspace_id=p_workspace_id AND journal_id=jid FOR UPDATE;SELECT count(*),coalesce(sum(debit),0),coalesce(sum(credit),0) INTO cnt,d,cr FROM public.office_accounting_journal_lines WHERE workspace_id=p_workspace_id AND journal_id=jid;IF cnt<2 OR d<>cr OR d=0 THEN RAISE EXCEPTION 'Journal must have at least two balanced lines' USING ERRCODE='22023';END IF;UPDATE public.office_accounting_journals SET status='submitted',submitted_at=now(),total_debit=d,total_credit=cr,version=version+1,updated_at=now() WHERE workspace_id=p_workspace_id AND journal_id=jid AND status IN('draft','returned') AND version=v RETURNING to_jsonb(office_accounting_journals.*) INTO result;
ELSIF p_action IN('approve_journal','return_journal') THEN jid:=(p_payload->>'journal_id')::uuid;IF NOT (p_payload ? 'expected_version') THEN RAISE EXCEPTION 'expected_version required' USING ERRCODE='40001';END IF;IF p_action='return_journal' AND length(trim(coalesce(p_payload->>'reason','')))<1 THEN RAISE EXCEPTION 'Return reason required' USING ERRCODE='22023';END IF;SELECT client_id,prepared_by,version INTO cid,aid,v FROM public.office_accounting_journals WHERE workspace_id=p_workspace_id AND journal_id=jid FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'Journal not found in workspace' USING ERRCODE='22023';END IF;PERFORM office_private.accounting_require(p_workspace_id,ARRAY['accounting_admin','engagement_manager','reviewer'],cid);IF aid=auth.uid() THEN RAISE EXCEPTION 'Independent reviewer required' USING ERRCODE='42501';END IF;IF v<>(p_payload->>'expected_version')::bigint THEN RAISE EXCEPTION 'Journal version conflict' USING ERRCODE='40001';END IF;UPDATE public.office_accounting_journals SET status=CASE WHEN p_action='approve_journal' THEN 'approved' ELSE 'returned' END,description=CASE WHEN p_action='return_journal' THEN description||' [Returned: '||(p_payload->>'reason')||']' ELSE description END,reviewed_by=auth.uid(),reviewed_at=now(),version=version+1,updated_at=now() WHERE workspace_id=p_workspace_id AND journal_id=jid AND status='submitted' AND version=v RETURNING to_jsonb(office_accounting_journals.*) INTO result;
