ct open unmatched posted line required' USING ERRCODE='22023'; END IF; UPDATE public.office_accounting_statement_lines SET matched_journal_line_id=(p_payload->>'journal_line_id')::uuid,matched_at=now(),matched_by=auth.uid(),status='matched',version=version+1,updated_at=now() WHERE workspace_id=p_workspace_id AND statement_line_id=(p_payload->>'statement_line_id')::uuid RETURNING jsonb_build_object('statement_line_id',statement_line_id,'status',status,'version',version) INTO result;
