ted_at=now() WHERE workspace_id=p_workspace_id AND statement_line_id=(p_payload->>'statement_line_id')::uuid RETURNING jsonb_build_object('statement_line_id',statement_line_id,'status',status,'version',version) INTO result; END IF;
