ELSIF p_action='supersede_evidence_reference' THEN
 IF NOT (p_payload ? 'expected_version') OR NULLIF(p_payload->>'expected_version','') IS NULL THEN RAISE EXCEPTION 'expected_version required' USING ERRCODE='40001'; END IF;
 SELECT client_id,engagement_id,version INTO cid,eid,v FROM public.office_accounting_evidence WHERE workspace_id=p_workspace_id AND evidence_id=(p_payload->>'evidence_id')::uuid AND status='active' FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Evidence not found in workspace' USING ERRCODE='22023'; END IF;
 PERFORM office_private.accounting_require(p_workspace_id,ARRAY['accounting_admin','engagement_manager','accountant','reviewer','client_coordinator'],cid); IF v<>(p_payload->>'expected_version')::bigint THEN RAISE EXCEPTION 'Evidence version conflict' USING ERRCODE='40001'; END IF;
 UPDATE public.office_accounting_evidence SET status='superseded',version=version+1,updated_at=now() WHERE workspace_id=p_workspace_id AND evidence_id=(p_payload->>'evidence_id')::uuid AND status='active' AND version=v RETURNING to_jsonb(office_accounting_evidence.*) INTO result;
ELSIF p_action='save_finding' THEN
 IF NULLIF(p_payload->>'client_id','') IS NULL OR NULLIF(p_payload->>'engagement_id','') IS NULL THEN RAISE EXCEPTION 'Client and engagement required' USING ERRCODE='22023'; END IF;
 cid:=(p_payload->>'client_id')::uuid; eid:=(p_payload->>'engagement_id')::uuid; PERFORM office_private.accounting_require(p_workspace_id,ARRAY['accounting_admin','engagement_manager','accountant','reviewer'],cid);
 IF NOT EXISTS(SELECT 1 FROM public.office_accounting_engagements e WHERE e.workspace_id=p_workspace_id AND e.engagement_id=eid AND e.client_id=cid) THEN RAISE EXCEPTION 'Validated linked engagement required' USING ERRCODE='22023'; END IF;
 IF NULLIF(p_payload->>'evidence_id','') IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.office_accounting_evidence x WHERE x.workspace_id=p_workspace_id AND x.evidence_id=(p_payload->>'evidence_id')::uuid AND x.client_id=cid AND x.engagement_id=eid) THEN RAISE EXCEPTION 'Evidence must match finding client and engagement' USING ERRCODE='22023'; END IF;
 INSERT INTO public.office_accounting_findings(workspace_id,client_id,engagement_id,evidence_id,finding_code,title,description_public,severity,owner_user_id,created_by) VALUES(p_workspace_id,cid,eid,NULLIF(p_payload->>'evidence_id','')::uuid,p_payload->>'finding_code',p_payload->>'title',p_payload->>'description_public',p_payload->>'severity',(p_payload->>'owner_user_id')::uuid,auth.uid()) RETURNING to_jsonb(office_accounting_findings.*) INTO result;
ELSIF p_action='transition_finding' THEN
 IF NOT (p_payload ? 'expected_version') OR NULLIF(p_payload->>'expected_version','') IS NULL OR (p_payload->>'status') NOT IN('open','management_response','resolved','closed') THEN RAISE EXCEPTION 'Valid status and expected_version required' USING ERRCODE='22023'; END IF;
 SELECT client_id,engagement_id,status,version INTO cid,eid,old,v FROM public.office_accounting_findings WHERE workspace_id=p_workspace_id AND finding_id=(p_payload->>'finding_id')::uuid FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Finding not found in workspace' USING ERRCODE='22023'; END IF;
 PERFORM office_private.accounting_require(p_workspace_id,ARRAY['accounting_admin','engagement_manager','accountant','reviewer'],cid); IF v<>(p_payload->>'expected_version')::bigint THEN RAISE EXCEPTION 'Finding version conflict' USING ERRCODE='40001'; END IF;
 IF NOT ((old='open' AND (p_payload->>'status')='management_response') OR (old='management_response' AND (p_payload->>'status')='resolved')) THEN RAISE EXCEPTION 'Invalid finding status transition' USING ERRCODE='22023'; END IF;
 UPDATE public.office_accounting_findings SET status=p_payload->>'status',version=version+1,updated_at=now() WHERE workspace_id=p_workspace_id AND finding_id=(p_payload->>'finding_id')::uuid AND version=v RETURNING to_jsonb(office_accounting_findings.*) INTO result;
ELSIF p_action='close_finding' THEN
 IF NOT (p_payload ? 'expected_version') OR NULLIF(p_payload->>'expected_version','') IS NULL OR NULLIF(p_payload->>'root_cause','') IS NULL OR NULLIF(p_payload->>'corrective_action','') IS NULL OR NULLIF(p_payload->>'evidence_id','') IS NULL THEN RAISE EXCEPTION 'Expected version, root cause, corrective action and evidence required' USING ERRCODE='22023'; END IF;
 SELECT client_id,engagement_id,status,owner_user_id,created_by,version INTO cid,eid,old,target,src,v FROM public.office_accounting_findings WHERE workspace_id=p_workspace_id AND finding_id=(p_payload->>'finding_id')::uuid FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Finding not found in workspace' USING ERRCODE='22023'; END IF;
 PERFORM office_private.accounting_require(p_workspace_id,ARRAY['accounting_admin','reviewer'],cid); IF auth.uid()=target OR auth.uid()=src THEN RAISE EXCEPTION 'Independent reviewer required' USING ERRCODE='42501'; END IF; IF old<>'resolved' THEN RAISE EXCEPTION 'Finding must be resolved before closure' USING ERRCODE='22023'; END IF; IF v<>(p_payload->>'expected_version')::bigint THEN RAISE EXCEPTION 'Finding version conflict' USING ERRCODE='40001'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.office_accounting_evidence x WHERE x.workspace_id=p_workspace_id AND x.evidence_id=(p_payload->>'evidence_id')::uuid AND x.client_id=cid AND x.engagement_id=eid AND x.status='active') THEN RAISE EXCEPTION 'Closure evidence must match finding client and engagement' USING ERRCODE='22023'; END IF;
 UPDATE public.office_accounting_findings SET status='closed',resolution_public=concat('Root cause: ',p_payload->>'root_cause','; Corrective action: ',p_payload->>'corrective_action'),evidence_id=(p_payload->>'evidence_id')::uuid,closed_by=auth.uid(),version=version+1,updated_at=now() WHERE workspace_id=p_workspace_id AND finding_id=(p_payload->>'finding_id')::uuid AND status='resolved' AND version=v RETURNING to_jsonb(office_accounting_findings.*) INTO result;
ELSIF p_action='save_obligation' THEN
 IF NULLIF(p_payload->>'client_id','') IS NULL OR NULLIF(p_payload->>'obligation_type','') IS NULL OR NULLIF(p_payload->>'authority_label','') IS NULL OR NULLIF(p_payload->>'period_label','') IS NULL OR NULLIF(p_payload->>'due_date','') IS NULL THEN RAISE EXCEPTION 'Client and obligation fields required' USING ERRCODE='22023'; END IF;
 cid:=(p_payload->>'client_id')::uuid; PERFORM office_private.accounting_require(p_workspace_id,ARRAY['accounting_admin','engagement_manager','accountant','client_coordinator'],cid); eid:=NULLIF(p_payload->>'engagement_id','')::uuid; IF eid IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.office_accounting_engagements e WHERE e.workspace_id=p_workspace_id AND e.engagement_id=eid AND e.client_id=cid) THEN RAISE EXCEPTION 'Validated linked engagement required' USING ERRCODE='22023'; END IF;
 IF coalesce(p_payload->>'status','planned') NOT IN('planned','in_progress','ready','filed_reference_recorded','closed','overdue') THEN RAISE EXCEPTION 'Invalid obligation status' USING ERRCODE='22023'; END IF;
 INSERT INTO public.office_accounting_obligations(workspace_id,client_id,engagement_id,obligation_type,authority_label,period_label,due_date,status,created_by) VALUES(p_workspace_id,cid,eid,p_payload->>'obligation_type',p_payload->>'authority_label',p_payload->>'period_label',(p_payload->>'due_date')::date,coalesce(p_payload->>'status','planned'),auth.uid()) RETURNING to_jsonb(office_accounting_obligations.*) INTO result;
ELSIF p_action='transition_obligation' THEN
 IF NOT (p_payload ? 'expected_version') OR NULLIF(p_payload->>'expected_version','') IS NULL OR (p_payload->>'status') NOT IN('planned','in_progress','ready','filed_reference_recorded','closed','overdue') THEN RAISE EXCEPTION 'Valid status and expected_version required' USING ERRCODE='22023'; END IF;
 SELECT client_id,engagement_id,status,version INTO cid,eid,old,v FROM public.office_accounting_obligations WHERE workspace_id=p_workspace_id AND obligation_id=(p_payload->>'obligation_id')::uuid FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Obligation not found in workspace' USING ERRCODE='22023'; END IF;
 PERFORM office_private.accounting_require(p_workspace_id,ARRAY['accounting_admin','engagement_manager','accountant','client_coordinator'],cid); IF v<>(p_payload->>'expected_version')::bigint THEN RAISE EXCEPTION 'Obligation version conflict' USING ERRCODE='40001'; END IF;
 IF NOT ((old='planned' AND (p_payload->>'status') IN('in_progress','overdue')) OR (old='in_progress' AND (p_payload->>'status') IN('ready','overdue')) OR (old='overdue' AND (p_payload->>'status')='in_progress') OR (old='ready' AND (p_payload->>'status')='in_progress')) THEN RAISE EXCEPTION 'Invalid obligation status transition' USING ERRCODE='22023'; END IF;
 UPDATE public.office_accounting_obligations SET status=p_payload->>'status',version=version+1,updated_at=now() WHERE workspace_id=p_workspace_id AND obligation_id=(p_payload->>'obligation_id')::uuid AND version=v RETURNING to_jsonb(office_accounting_obligations.*) INTO result;
ELSIF p_action='record_filing_reference' THEN
 url:=p_payload->>'official_link'; IF NULLIF(p_payload->>'filing_reference','') IS NULL OR url !~ '^https://[^/:@[:space:]]+(:[0-9]+)?(/[^[:space:]]*)?$' THEN RAISE EXCEPTION 'Human filing reference and HTTPS official host required' USING ERRCODE='22023'; END IF; IF NOT (p_payload ? 'expected_version') OR NULLIF(p_payload->>'expected_version','') IS NULL THEN RAISE EXCEPTION 'expected_version required' USING ERRCODE='40001'; END IF;
 SELECT client_id,engagement_id,status,version INTO cid,eid,old,v FROM public.office_accounting_obligations WHERE workspace_id=p_workspace_id AND obligation_id=(p_payload->>'obligation_id')::uuid FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Obligation not found in workspace' USING ERRCODE='22023'; END IF;
 PERFORM office_private.accounting_require(p_workspace_id,ARRAY['accounting_admin','engagement_manager','accountant','client_coordinator'],cid); IF v<>(p_payload->>'expected_version')::bigint THEN RAISE EXCEPTION 'Obligation version conflict' USING ERRCODE='40001'; END IF; IF old<>'ready' THEN RAISE EXCEPTION 'Obligation must be ready before filing reference' USING ERRCODE='22023'; END IF;
 UPDATE public.office_accounting_obligations SET filing_reference=p_payload->>'filing_reference',filed_on=(p_payload->>'filed_on')::date,official_link=url,status='filed_reference_recorded',version=version+1,updated_at=now() WHERE workspace_id=p_workspace_id AND obligation_id=(p_payload->>'obligation_id')::uuid AND version=v RETURNING to_jsonb(office_accounting_obligations.*) INTO result;
ELSE RAISE EXCEPTION 'Unknown Accounting action' USING ERRCODE='22023';END IF;
IF result IS NULL THEN RAISE EXCEPTION 'Command did not produce a result' USING ERRCODE='22023';END IF;INSERT INTO public.office_accounting_requests(workspace_id,idempotency_key,actor_id,action,request_hash,response) VALUES(p_workspace_id,idem,auth.uid(),p_action,h,result);INSERT INTO public.office_accounting_audit(workspace_id,client_id,actor_user_id,action,resource,entity_id,idempotency_key,after_digest) VALUES(p_workspace_id,cid,auth.uid(),p_action,split_part(p_action,'_',2),coalesce((result->>'evidence_id')::uuid,(result->>'finding_id')::uuid,(result->>'obligation_id')::uuid,(result->>'line_id')::uuid,(result->>'statement_line_id')::uuid,(result->>'posting_id')::uuid,(result->>'journal_id')::uuid,(result->>'period_id')::uuid,(result->>'account_id')::uuid,(result->>'bank_account_id')::uuid,(result->>'statement_id')::uuid,(result->>'engagement_id')::uuid,(result->>'user_id')::uuid,(result->>'client_id')::uuid,(result->>'workspace_id')::uuid),idem,encode(pg_catalog.sha256(pg_catalog.convert_to(result::text,'UTF8')),'hex'));RETURN result;END$$;

DO $$ DECLARE item record; BEGIN
 FOR item IN SELECT tablename FROM pg_tables WHERE schemaname='public' AND tablename LIKE 'office_accounting_%' LOOP
  EXECUTE format('REVOKE ALL ON TABLE public.%I FROM PUBLIC,anon,authenticated,service_role',item.tablename);
 END LOOP;
 FOR item IN SELECT c.relname FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind='S' AND c.relname LIKE 'office_accounting_%' LOOP
  EXECUTE format('REVOKE ALL ON SEQUENCE public.%I FROM PUBLIC,anon,authenticated,service_role',item.relname);
 END LOOP;
 FOR item IN SELECT p.oid::regprocedure AS signature FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE (n.nspname='office_private' AND p.proname LIKE 'accounting_%') OR (n.nspname='public' AND p.proname LIKE 'office_accounting_%') LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC,anon,authenticated,service_role',item.signature);
 END LOOP;
END $$;
REVOKE ALL ON FUNCTION public.office_accounting_read(uuid,text,jsonb,integer,integer),public.office_accounting_command(uuid,text,jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.office_accounting_read(uuid,text,jsonb,integer,integer),public.office_accounting_command(uuid,text,jsonb) TO authenticated;
COMMIT;
